'use client';

import React, { useState, useEffect } from 'react';
import './ProductMainSection.css';

export interface ProductVariant {
  id: string | number;
  name: string;
  image: string;
}

export interface ProductMainProps {
  title?: string;
  rating?: number | null;
  reviewsCount?: number;
  soldCount?: string;
  currentPrice?: string;
  originalPrice?: string;
  discount?: string;
  images?: string[];
  variants?: ProductVariant[];
  onAddToCart?: (quantity: number, selectedVariant: ProductVariant | null) => void;
  onBuyNow?: (quantity: number, selectedVariant: ProductVariant | null) => void;
}

const defaultImages = [
  'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=500&q=80',
  'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=500&q=80',
];

const defaultVariants: ProductVariant[] = [
  { id: 1, name: 'Standard', image: 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=100&q=80' },
];

export const ProductMainSection: React.FC<ProductMainProps> = ({
  title = 'سماعات ألعاب TWS جديدة تعمل بتقنية البلوتوث مع ميكروفون',
  rating = null,
  reviewsCount = 0,
  soldCount = '0',
  currentPrice = 'DA1,026',
  originalPrice = 'DA2,199.55',
  discount = '49%',
  images = defaultImages,
  variants = defaultVariants,
  onAddToCart,
  onBuyNow,
}) => {
  const [activeImage, setActiveImage] = useState<string>(images[0]);
  const [selectedVariant, setSelectedVariant] = useState<ProductVariant>(variants[0]);
  const [quantity, setQuantity] = useState<number>(1);

  useEffect(() => {
    if (images && images.length > 0) {
      setActiveImage(images[0]);
    }
    if (variants && variants.length > 0) {
      setSelectedVariant(variants[0]);
    }
  }, [images, variants]);

  const handleQuantityChange = (type: 'inc' | 'dec') => {
    if (type === 'inc') {
      setQuantity((prev) => prev + 1);
    } else if (type === 'dec' && quantity > 1) {
      setQuantity((prev) => prev - 1);
    }
  };

  return (
    <div className="product-main-container">
      <div className="product-gallery-section">
        <div className="main-image-wrapper">
          <img src={activeImage} alt={title} />
        </div>
        <div className="thumbnails-list">
          {images.map((img, index) => (
            <div
              key={index}
              className={`thumbnail-item ${activeImage === img ? 'active' : ''}`}
              onClick={() => setActiveImage(img)}
            >
              <img src={img} alt={`thumb-${index}`} />
            </div>
          ))}
        </div>
      </div>

      <div className="product-info-section">
        <h1 className="product-main-title">{title}</h1>

        <div className="product-rating-row">
          {rating ? (
            <>
              <span className="stars">⭐ {rating}</span>
              <span className="reviews-count">({reviewsCount} التقييمات)</span>
            </>
          ) : (
            <span className="no-rating-text">⭐ لا توجد تقييمات لهذا المنتج بعد</span>
          )}
          <span className="separator">|</span>
          <span className="sold-count">المبيعات: {soldCount}</span>
        </div>

        <div className="product-price-box">
          <span className="current-price">{currentPrice}</span>
          {originalPrice && <span className="original-price">{originalPrice}</span>}
          {discount && <span className="discount-badge">خصم {discount}</span>}
        </div>

        {variants.length > 0 && (
          <div className="variants-container">
            <span className="variant-label">الخيار: <strong>{selectedVariant?.name}</strong></span>
            <div className="variants-grid">
              {variants.map((v) => (
                <div
                  key={v.id}
                  className={`variant-card ${selectedVariant?.id === v.id ? 'active' : ''}`}
                  onClick={() => {
                    setSelectedVariant(v);
                    setActiveImage(v.image);
                  }}
                >
                  <img src={v.image} alt={v.name} />
                </div>
              ))}
            </div>
          </div>
        )}

        <div className="quantity-section">
          <span className="section-title">الكمية:</span>
          <div className="quantity-selector">
            <button onClick={() => handleQuantityChange('dec')}>-</button>
            <span>{quantity}</span>
            <button onClick={() => handleQuantityChange('inc')}>+</button>
          </div>
        </div>

        <div className="product-actions-grid">
          <button
            className="action-btn buy-now-btn"
            onClick={() => onBuyNow?.(quantity, selectedVariant)}
          >
            شراء الآن
          </button>
          <button
            className="action-btn add-cart-btn"
            onClick={() => onAddToCart?.(quantity, selectedVariant)}
          >
            أضف إلى العربة
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProductMainSection;